// System QA (2026-08-07): real-data cutover. Gated by env, not a
// hardcoded disable, so CI / fresh deployments (no LDI_SIMULATOR_ENABLED
// set) keep generating mock data by default -- only this specific
// environment's local .env (gitignored, never committed) turns it off.
if (env.get('LDI_SIMULATOR_ENABLED') === 'false') {
    node.status({ fill: 'grey', shape: 'ring', text: 'disabled (real-data mode)' });
    return null;
}


// ══════════════════════════════════════════════════════════════════
// LDI ALARM SIMULATOR — noise codes (real distribution, uncorrelated
// equipment/calibration faults) + condition-driven codes (fired only
// when the matching telemetry parameter is actually out of spec right
// now, per the same thresholds v_ldi_alarm_context/migration 054+057
// uses).
//
// IMS-FULL-SYSTEM-AUDIT.md P0-2: previously every code (including the
// process-linked ones like 91009/90005/91008/70004) was drawn from a
// pure Poisson/weighted-random process independent of telemetry, so
// the RCA Truth Test correctly reported Lift ≈ 1 (no correlation to
// find, because there was none by construction). Codes with a known
// real-world parameter link now only fire when that parameter is
// actually out of spec, so Lift should rise meaningfully (> 2).
//
// VACUUM (91009), System QA realism audit 2026-08-06: previously
// left as pure noise because the -50/-95 kPa threshold it was checked
// against didn't match ANY simulated value (not even DF INNER's real
// -16..-19 kPa baseline), so flag_vac_out_of_spec was true for ~100% of
// all rows regardless of timing -- no alarm-timing strategy could raise
// Lift above ~1 when the baseline itself was saturated. Migration 057
// recalibrates the threshold to bound around the simulator's own DF
// INNER recipe range (simulator-derived, not a sourced vendor spec) and
// the telemetry generator now injects rare weak-vacuum fault events
// (ldisim_gen, vacFaultTicks) so there's a real excursion to correlate
// against. 91009 moves from the noise pool to condition-driven, same
// pattern as 91008/align/70004.
// ══════════════════════════════════════════════════════════════════
const pool = global.get('pgPool');
if (!pool) { node.status({ fill: 'red', shape: 'ring', text: 'no pgPool' }); return null; }

// codes with no known telemetry correlation - unconditioned background
// noise. System QA (2026-08-07): replaced with real codes from the
// vendor Alarm Master import (migration 061) -- 91012/91017/91020/91024/
// 93007/91029/97014/20/20021/2 never existed in the real 1,820-code list
// (invented for early prototyping); swapped 1:1 for real generic-fault
// codes (camera/PLC/comms/network/DB), keeping the exact same weights.
// 90013 (5th ALIGN_CODES entry) also didn't exist in the real list --
// dropped rather than force-substituted, since 4 real alignment codes
// already cover the category.
const NOISE_CUM = [["93004", 24.5], ["01060009", 31.3], ["0106000C", 38.2],
    ["0106001C", 45.0], ["01060013", 51.8], ["01100001", 58.7], ["01130002", 65.5], ["010E0064", 72.4],
    ["10006", 79.2], ["92013", 86.0], ["97005", 92.9], ["80001", 100.0]];
const MACHINES = [["LDI-01", 16.6], ["LDI-02", 33.2], ["LDI-03", 44.1], ["LDI-04", 55.0],
    ["LDI-05", 72.2], ["LDI-06", 89.3], ["LDI-07", 93.0], ["LDI-08", 96.7],
    ["LDI-09", 98.4], ["LDI-10", 100.0]];
// alignment codes correlated to PE/JE out-of-tolerance (misalignment <-> PE error)
const ALIGN_CODES = ["90001", "90004", "90005", "90012"];
const RATE_PER_TICK = 0.01194 * 20 * (15 / 20); // unchanged overall pacing, noise share only

function pick(table) {
    const x = Math.random() * 100;
    for (const [v, c] of table) if (x <= c) return v;
    return table[table.length - 1][0];
}
function poissonCount(rate) {
    let n = 0, L = Math.exp(-rate), p = 1;
    do { p *= Math.random(); n++; } while (p > L);
    return n - 1;
}
// relatedLogId: the literal ldi_data.log_id of the telemetry row that
// triggered this alarm, when known (condition-driven codes only -- noise
// codes aren't tied to any specific board, so they pass null and let
// migration 051's trigger fall back to its nearest-match heuristic).
// System Audit Priority 3: production-grade exact event linkage.
function newRow(eq, code, ts, relatedLogId) {
    return {
        logid: 'SIM-ALM-' + ts.getTime() + '-' + eq + '-' + code + '-' + Math.floor(Math.random() * 1e6),
        logdate: ts.toISOString(),
        errorcode: code,
        errortime: ts.toISOString().replace('T', ' ').substring(0, 19),
        equipmentid: eq,
        factory: Math.random() < 0.75 ? '2' : '3',
        process: ['DF INNER', 'DF OUTER', 'SM'][Math.floor(Math.random() * 3)],
        related_log_id: relatedLogId || null
    };
}

const rows = [];
const now = Date.now();

// ── background noise (unconditioned, real historical distribution) ──
const nNoise = poissonCount(RATE_PER_TICK);
for (let k = 0; k < nNoise; k++) {
    rows.push(newRow(pick(MACHINES), pick(NOISE_CUM), new Date(now - Math.floor(Math.random() * 9000))));
}

// ── condition-driven alarms: only fire when telemetry is actually out of
//    spec right now, using the same thresholds as v_ldi_alarm_context ──
const sql = `
    SELECT DISTINCT ON (eqp_id) eqp_id, process, temperature, humidity,
           pe_1, je_1, scan_speed, air_vacuum, log_id
    FROM public.ldi_data
    WHERE time > NOW() - INTERVAL '3 minutes'
    ORDER BY eqp_id, time DESC`;

pool.query(sql, [], function (err, result) {
    if (err) { node.error('Alarm sim telemetry query failed: ' + err.message); return; }
    const ts = new Date();
    // ~25%/tick per condition so a persistently out-of-spec machine doesn't
    // fire an alarm on literally every 10s tick while the fault holds
    const fires = () => Math.random() < 0.25;
    for (const r of (result.rows || [])) {
        if ((r.temperature < 20 || r.temperature > 24 || r.humidity < 50 || r.humidity > 60) && fires()) {
            rows.push(newRow(r.eqp_id, '91008', ts, r.log_id));
        }
        if ((Math.abs(r.pe_1) > 10 || Math.abs(r.je_1) > 10) && fires()) {
            rows.push(newRow(r.eqp_id, ALIGN_CODES[Math.floor(Math.random() * ALIGN_CODES.length)], ts, r.log_id));
        }
        if ((r.scan_speed > 450 || r.scan_speed <= 0) && fires()) {
            rows.push(newRow(r.eqp_id, '70004', ts, r.log_id));
        }
        if (r.air_vacuum !== null && (r.air_vacuum > -8 || r.air_vacuum < -30) && fires()) {
            rows.push(newRow(r.eqp_id, '91009', ts, r.log_id));
        }
    }

    if (rows.length === 0) { node.status({ fill: 'grey', shape: 'ring', text: 'no alarm' }); return; }
    node.status({ fill: 'yellow', shape: 'dot',
        text: rows.length + ' alarm: ' + rows.map(r => r.errorcode).join(',') });
    node.send({ payload: rows });
});
return null;

const pool = global.get('pgPool');
const rows = msg.payload || [];
if (!pool || rows.length === 0) return null;
const cols = ['logid','logdate','errorcode','errortime','equipmentid','factory','process','related_log_id'];
const ph = rows.map((_, i) => '(' + cols.map((_, j) => '$' + (i * cols.length + j + 1)).join(',') + ')').join(',');
const params = [];
for (const r of rows) for (const c of cols) params.push(r[c]);
const sql = 'INSERT INTO public.ldi_alarm_log (' + cols.join(',') + ') VALUES ' + ph +
            ' ON CONFLICT (logdate, logid) DO NOTHING';
pool.query(sql, params, function (err) {
    if (err) { node.error('Alarm sim INSERT failed: ' + err.message); return; }
    node.log('Alarm sim: inserted ' + rows.length);
});
return null;
